using FixFinder.Core.LocalFixes;
using FixFinder.Core.Logic;

namespace FixFinder.Tests;

/// <summary>
/// A count left out of step, in TypeScript, Ruby, PHP, Lua, Perl, Dart, PowerShell, Scala and Rust: a stack's push adds an
/// item and 1 to size, and its pop takes an item out and leaves size as it was. Left alone in each: each found program put
/// right, a pop setting size from the list's length, and one leaving the work to another method - with TypeScript's running
/// total of pushes that is not a count; and a JavaScript file, whose classes the analysis follows.
/// </summary>
public class CountOutOfStepPatternsTests
{
    private static IReadOnlyList<LogicFinding> Scanned(string fileName, string code) =>
        LogicPatterns.Scan(new SourceFile { Path = Path.Combine(Path.GetTempPath(), fileName), Lines = code.Replace("\r\n", "\n").Split('\n') })
            .Where(finding => finding.PatternId.EndsWith("-count-out-of-step", StringComparison.Ordinal))
            .ToList();

    /// <summary>The file, the program, and what the check said of it here: the finding's line, check and words.</summary>
    public static TheoryData<string, string, string> Found => new()
    {
        { "stack.dart", "class Stack {\n  final List<int> items = [];\n  int size = 0;\n\n  void push(int item) {\n    items.add(item);\n    size++;\n  }\n\n  int pop() {\n    return items.removeLast();\n  }\n\n  int count() {\n    return size;\n  }\n}\n\nvoid main() {\n  final stack = Stack();\n  for (var item in [1, 2, 3]) {\n    stack.push(item);\n  }\n  stack.pop();\n  print(stack.count());\n}\n", "11|logic-dart-count-out-of-step|`pop` takes an item out of `items` but leaves `size` as it was, while `push` changes both - after it, `size` no longer says how many `items` holds" },
        { "stack.lua", "local Stack = {}\nStack.__index = Stack\n\nfunction Stack.new()\n  return setmetatable({ items = {}, size = 0 }, Stack)\nend\n\nfunction Stack:push(item)\n  table.insert(self.items, item)\n  self.size = self.size + 1\nend\n\nfunction Stack:pop()\n  return table.remove(self.items)\nend\n\nfunction Stack:count()\n  return self.size\nend\n\nlocal stack = Stack.new()\nfor _, item in ipairs({1, 2, 3}) do\n  stack:push(item)\nend\nstack:pop()\nprint(stack:count())\n", "14|logic-lua-count-out-of-step|`pop` takes an item out of `items` but leaves `size` as it was, while `push` changes both - after it, `size` no longer says how many `items` holds" },
        { "stack.php", "<?php\nclass Stack\n{\n    private array $items = [];\n    private int $size = 0;\n\n    public function push(int $item): void\n    {\n        $this->items[] = $item;\n        $this->size++;\n    }\n\n    public function pop(): int\n    {\n        return array_pop($this->items);\n    }\n\n    public function count(): int\n    {\n        return $this->size;\n    }\n}\n\n$stack = new Stack();\nforeach ([1, 2, 3] as $item) {\n    $stack->push($item);\n}\n$stack->pop();\necho $stack->count(), PHP_EOL;\n", "15|logic-php-count-out-of-step|`pop` takes an item out of `items` but leaves `size` as it was, while `push` changes both - after it, `size` no longer says how many `items` holds" },
        { "stack.pl", "use strict;\nuse warnings;\n\npackage Stack;\n\nsub new {\n    my ($class) = @_;\n    return bless { items => [], size => 0 }, $class;\n}\n\nsub push_item {\n    my ($self, $item) = @_;\n    push @{ $self->{items} }, $item;\n    $self->{size}++;\n}\n\nsub pop_item {\n    my ($self) = @_;\n    return pop @{ $self->{items} };\n}\n\nsub count {\n    my ($self) = @_;\n    return $self->{size};\n}\n\npackage main;\n\nmy $stack = Stack->new();\n$stack->push_item($_) for (1, 2, 3);\n$stack->pop_item();\nprint $stack->count(), \"\\n\";\n", "19|logic-perl-count-out-of-step|`pop_item` takes an item out of `items` but leaves `size` as it was, while `push_item` changes both - after it, `size` no longer says how many `items` holds" },
        { "stack.ps1", "class Stack {\n    [System.Collections.Generic.List[int]] $items = [System.Collections.Generic.List[int]]::new()\n    [int] $size = 0\n\n    [void] Push([int] $item) {\n        $this.items.Add($item)\n        $this.size++\n    }\n\n    [int] Pop() {\n        $top = $this.items[$this.items.Count - 1]\n        $this.items.RemoveAt($this.items.Count - 1)\n        return $top\n    }\n\n    [int] Count() {\n        return $this.size\n    }\n}\n\n$stack = [Stack]::new()\nforeach ($item in 1, 2, 3) {\n    $stack.Push($item)\n}\n[void] $stack.Pop()\n$stack.Count()\n", "12|logic-powershell-count-out-of-step|`Pop` takes an item out of `items` but leaves `size` as it was, while `Push` changes both - after it, `size` no longer says how many `items` holds" },
        { "stack.rb", "class Stack\n  def initialize\n    @items = []\n    @size = 0\n  end\n\n  def push(item)\n    @items << item\n    @size += 1\n  end\n\n  def pop\n    @items.pop\n  end\n\n  def count\n    @size\n  end\nend\n\nstack = Stack.new\n[1, 2, 3].each { |item| stack.push(item) }\nstack.pop\nputs stack.count\n", "13|logic-ruby-count-out-of-step|`pop` takes an item out of `items` but leaves `size` as it was, while `push` changes both - after it, `size` no longer says how many `items` holds" },
        { "stack.rs", "struct Stack {\n    items: Vec<i32>,\n    size: usize,\n}\n\nimpl Stack {\n    fn new() -> Self {\n        Stack { items: Vec::new(), size: 0 }\n    }\n\n    fn push(&mut self, item: i32) {\n        self.items.push(item);\n        self.size += 1;\n    }\n\n    fn pop(&mut self) -> Option<i32> {\n        self.items.pop()\n    }\n\n    fn count(&self) -> usize {\n        self.size\n    }\n}\n\nfn main() {\n    let mut stack = Stack::new();\n    for item in [1, 2, 3] {\n        stack.push(item);\n    }\n    stack.pop();\n    println!(\"{}\", stack.count());\n}\n", "17|logic-rust-count-out-of-step|`pop` takes an item out of `items` but leaves `size` as it was, while `push` changes both - after it, `size` no longer says how many `items` holds" },
        { "Stack.scala", "import scala.collection.mutable.ListBuffer\n\nclass Stack {\n  private val items = ListBuffer[Int]()\n  private var size = 0\n\n  def push(item: Int): Unit = {\n    items += item\n    size += 1\n  }\n\n  def pop(): Int = {\n    items.remove(items.length - 1)\n  }\n\n  def count(): Int = size\n}\n\nobject Main {\n  def main(args: Array[String]): Unit = {\n    val stack = new Stack()\n    for (item <- List(1, 2, 3)) {\n      stack.push(item)\n    }\n    stack.pop()\n    println(stack.count())\n  }\n}\n", "13|logic-scala-count-out-of-step|`pop` takes an item out of `items` but leaves `size` as it was, while `push` changes both - after it, `size` no longer says how many `items` holds" },
        { "stack.ts", "class Stack {\n  private items: number[] = [];\n  private size: number = 0;\n\n  push(item: number): void {\n    this.items.push(item);\n    this.size += 1;\n  }\n\n  pop(): number | undefined {\n    return this.items.pop();\n  }\n\n  count(): number {\n    return this.size;\n  }\n}\n\nconst stack = new Stack();\nfor (const item of [1, 2, 3]) {\n  stack.push(item);\n}\nstack.pop();\nconsole.log(stack.count());\n", "11|logic-typescript-count-out-of-step|`pop` takes an item out of `items` but leaves `size` as it was, while `push` changes both - after it, `size` no longer says how many `items` holds" },
    };

    /// <summary>The file, and a program the check must leave alone: each found program put right, and the near misses.</summary>
    public static TheoryData<string, string> NearMisses => new()
    {
        { "stack.dart", "class Stack {\n  final List<int> items = [];\n  int size = 0;\n\n  void push(int item) {\n    items.add(item);\n    size++;\n  }\n\n  int pop() {\n    size--;\n    return items.removeLast();\n  }\n\n  int count() {\n    return size;\n  }\n}\n\nvoid main() {\n  final stack = Stack();\n  for (var item in [1, 2, 3]) {\n    stack.push(item);\n  }\n  stack.pop();\n  print(stack.count());\n}\n" },
        { "stack.lua", "local Stack = {}\nStack.__index = Stack\n\nfunction Stack.new()\n  return setmetatable({ items = {}, size = 0 }, Stack)\nend\n\nfunction Stack:push(item)\n  table.insert(self.items, item)\n  self.size = self.size + 1\nend\n\nfunction Stack:pop()\n  self.size = self.size - 1\n  return table.remove(self.items)\nend\n\nfunction Stack:count()\n  return self.size\nend\n\nlocal stack = Stack.new()\nfor _, item in ipairs({1, 2, 3}) do\n  stack:push(item)\nend\nstack:pop()\nprint(stack:count())\n" },
        { "stack.php", "<?php\nclass Stack\n{\n    private array $items = [];\n    private int $size = 0;\n\n    public function push(int $item): void\n    {\n        $this->items[] = $item;\n        $this->size++;\n    }\n\n    public function pop(): int\n    {\n        $this->size--;\n        return array_pop($this->items);\n    }\n\n    public function count(): int\n    {\n        return $this->size;\n    }\n}\n\n$stack = new Stack();\nforeach ([1, 2, 3] as $item) {\n    $stack->push($item);\n}\n$stack->pop();\necho $stack->count(), PHP_EOL;\n" },
        { "stack.pl", "use strict;\nuse warnings;\n\npackage Stack;\n\nsub new {\n    my ($class) = @_;\n    return bless { items => [], size => 0 }, $class;\n}\n\nsub push_item {\n    my ($self, $item) = @_;\n    push @{ $self->{items} }, $item;\n    $self->{size}++;\n}\n\nsub pop_item {\n    my ($self) = @_;\n    $self->{size}--;\n    return pop @{ $self->{items} };\n}\n\nsub count {\n    my ($self) = @_;\n    return $self->{size};\n}\n\npackage main;\n\nmy $stack = Stack->new();\n$stack->push_item($_) for (1, 2, 3);\n$stack->pop_item();\nprint $stack->count(), \"\\n\";\n" },
        { "stack.ps1", "class Stack {\n    [System.Collections.Generic.List[int]] $items = [System.Collections.Generic.List[int]]::new()\n    [int] $size = 0\n\n    [void] Push([int] $item) {\n        $this.items.Add($item)\n        $this.size++\n    }\n\n    [int] Pop() {\n        $top = $this.items[$this.items.Count - 1]\n        $this.items.RemoveAt($this.items.Count - 1)\n        $this.size--\n        return $top\n    }\n\n    [int] Count() {\n        return $this.size\n    }\n}\n\n$stack = [Stack]::new()\nforeach ($item in 1, 2, 3) {\n    $stack.Push($item)\n}\n[void] $stack.Pop()\n$stack.Count()\n" },
        { "stack.rb", "class Stack\n  def initialize\n    @items = []\n    @size = 0\n  end\n\n  def push(item)\n    @items << item\n    @size += 1\n  end\n\n  def pop\n    @size -= 1\n    @items.pop\n  end\n\n  def count\n    @size\n  end\nend\n\nstack = Stack.new\n[1, 2, 3].each { |item| stack.push(item) }\nstack.pop\nputs stack.count\n" },
        { "stack.rs", "struct Stack {\n    items: Vec<i32>,\n    size: usize,\n}\n\nimpl Stack {\n    fn new() -> Self {\n        Stack { items: Vec::new(), size: 0 }\n    }\n\n    fn push(&mut self, item: i32) {\n        self.items.push(item);\n        self.size += 1;\n    }\n\n    fn pop(&mut self) -> Option<i32> {\n        self.size -= 1;\n        self.items.pop()\n    }\n\n    fn count(&self) -> usize {\n        self.size\n    }\n}\n\nfn main() {\n    let mut stack = Stack::new();\n    for item in [1, 2, 3] {\n        stack.push(item);\n    }\n    stack.pop();\n    println!(\"{}\", stack.count());\n}\n" },
        { "Stack.scala", "import scala.collection.mutable.ListBuffer\n\nclass Stack {\n  private val items = ListBuffer[Int]()\n  private var size = 0\n\n  def push(item: Int): Unit = {\n    items += item\n    size += 1\n  }\n\n  def pop(): Int = {\n    size -= 1\n    items.remove(items.length - 1)\n  }\n\n  def count(): Int = size\n}\n\nobject Main {\n  def main(args: Array[String]): Unit = {\n    val stack = new Stack()\n    for (item <- List(1, 2, 3)) {\n      stack.push(item)\n    }\n    stack.pop()\n    println(stack.count())\n  }\n}\n" },
        { "stack.ts", "class Stack {\n  private items: number[] = [];\n  private size: number = 0;\n\n  push(item: number): void {\n    this.items.push(item);\n    this.size += 1;\n  }\n\n  pop(): number | undefined {\n    this.size -= 1;\n    return this.items.pop();\n  }\n\n  count(): number {\n    return this.size;\n  }\n}\n\nconst stack = new Stack();\nfor (const item of [1, 2, 3]) {\n  stack.push(item);\n}\nstack.pop();\nconsole.log(stack.count());\n" },
        { "near.dart", "class Stack {\n  final List<int> items = [];\n  int size = 0;\n\n  void push(int item) {\n    items.add(item);\n    size++;\n  }\n\n  int pop() {\n    final top = items.removeLast();\n    size = items.length;\n    return top;\n  }\n\n  void drop() {\n    pop();\n  }\n}\n\nvoid main() {\n  final stack = Stack();\n  stack.push(1);\n  stack.drop();\n  print('done');\n}\n" },
        { "near.lua", "local Stack = {}\nStack.__index = Stack\n\nfunction Stack.new()\n  return setmetatable({ items = {}, size = 0 }, Stack)\nend\n\nfunction Stack:push(item)\n  table.insert(self.items, item)\n  self.size = self.size + 1\nend\n\nfunction Stack:pop()\n  local top = table.remove(self.items)\n  self.size = #self.items\n  return top\nend\n\nfunction Stack:drop()\n  self:pop()\nend\n\nlocal stack = Stack.new()\nstack:push(1)\nstack:drop()\nprint(\"done\")\n" },
        { "near.php", "<?php\nclass Stack\n{\n    private array $items = [];\n    private int $size = 0;\n\n    public function push(int $item): void\n    {\n        $this->items[] = $item;\n        $this->size++;\n    }\n\n    public function pop(): int\n    {\n        $top = array_pop($this->items);\n        $this->size = count($this->items);\n        return $top;\n    }\n\n    public function drop(): void\n    {\n        $this->pop();\n    }\n}\n\n$stack = new Stack();\n$stack->push(1);\n$stack->drop();\necho \"done\", PHP_EOL;\n" },
        { "near.pl", "use strict;\nuse warnings;\n\npackage Stack;\n\nsub new {\n    my ($class) = @_;\n    return bless { items => [], size => 0 }, $class;\n}\n\nsub push_item {\n    my ($self, $item) = @_;\n    push @{ $self->{items} }, $item;\n    $self->{size}++;\n}\n\nsub pop_item {\n    my ($self) = @_;\n    my $top = pop @{ $self->{items} };\n    $self->{size} = scalar @{ $self->{items} };\n    return $top;\n}\n\nsub drop {\n    my ($self) = @_;\n    $self->pop_item();\n}\n\npackage main;\n\nmy $stack = Stack->new();\n$stack->push_item(1);\n$stack->drop();\nprint \"done\\n\";\n" },
        { "near.ps1", "class Stack {\n    [System.Collections.Generic.List[int]] $items = [System.Collections.Generic.List[int]]::new()\n    [int] $size = 0\n\n    [void] Push([int] $item) {\n        $this.items.Add($item)\n        $this.size++\n    }\n\n    [int] Pop() {\n        $top = $this.items[$this.items.Count - 1]\n        $this.items.RemoveAt($this.items.Count - 1)\n        $this.size = $this.items.Count\n        return $top\n    }\n\n    [void] Drop() {\n        [void] $this.Pop()\n    }\n}\n\n$stack = [Stack]::new()\n$stack.Push(1)\n$stack.Drop()\n\"done\"\n" },
        { "near.rb", "class Stack\n  def initialize\n    @items = []\n    @size = 0\n  end\n\n  def push(item)\n    @items << item\n    @size += 1\n  end\n\n  def pop\n    top = @items.pop\n    @size = @items.length\n    top\n  end\n\n  def drop\n    pop\n  end\nend\n\nstack = Stack.new\nstack.push(1)\nstack.drop\nputs \"done\"\n" },
        { "near.rs", "struct Stack {\n    items: Vec<i32>,\n    size: usize,\n}\n\nimpl Stack {\n    fn new() -> Self {\n        Stack { items: Vec::new(), size: 0 }\n    }\n\n    fn push(&mut self, item: i32) {\n        self.items.push(item);\n        self.size += 1;\n    }\n\n    fn pop(&mut self) -> Option<i32> {\n        let top = self.items.pop();\n        self.size = self.items.len();\n        top\n    }\n\n    fn drop_top(&mut self) {\n        self.pop();\n    }\n}\n\nfn main() {\n    let mut stack = Stack::new();\n    stack.push(1);\n    stack.drop_top();\n    println!(\"done\");\n}\n" },
        { "Near.scala", "import scala.collection.mutable.ListBuffer\n\nclass Stack {\n  private val items = ListBuffer[Int]()\n  private var size = 0\n\n  def push(item: Int): Unit = {\n    items += item\n    size += 1\n  }\n\n  def pop(): Int = {\n    val top = items.remove(items.length - 1)\n    size = items.length\n    top\n  }\n\n  def drop(): Unit = {\n    pop()\n  }\n}\n\nobject Near {\n  def main(args: Array[String]): Unit = {\n    val stack = new Stack()\n    stack.push(1)\n    stack.drop()\n    println(\"done\")\n  }\n}\n" },
        { "near.ts", "class History {\n  private items: number[] = [];\n  private pushes: number = 0;\n\n  push(item: number): void {\n    this.items.push(item);\n    this.pushes += 1;\n  }\n\n  pop(): number | undefined {\n    return this.items.pop();\n  }\n}\n\nclass Stack {\n  private items: number[] = [];\n  private size: number = 0;\n\n  push(item: number): void {\n    this.items.push(item);\n    this.size += 1;\n  }\n\n  pop(): number | undefined {\n    const top = this.items.pop();\n    this.size = this.items.length;\n    return top;\n  }\n\n  drop(): void {\n    this.pop();\n  }\n}\n\nconst history = new History();\nhistory.push(1);\nhistory.pop();\nconst stack = new Stack();\nstack.push(1);\nstack.drop();\nconsole.log(\"done\");\n" },
        { "stack.js", "class Stack {\n  constructor() {\n    this.items = [];\n    this.size = 0;\n  }\n\n  push(item) {\n    this.items.push(item);\n    this.size += 1;\n  }\n\n  pop() {\n    return this.items.pop();\n  }\n\n  count() {\n    return this.size;\n  }\n}\n\nconst stack = new Stack();\nfor (const item of [1, 2, 3]) {\n  stack.push(item);\n}\nstack.pop();\nconsole.log(stack.count());\n" },
    };

    [Theory]
    [MemberData(nameof(Found))]
    public void AMethodChangingOnlyOneOfTwoFieldsKeptTogetherIsFound(string fileName, string code, string said)
    {
        Assert.Equal([said], Scanned(fileName, code).Select(finding => $"{finding.Line}|{finding.PatternId}|{finding.Message}"));
    }

    [Theory]
    [MemberData(nameof(NearMisses))]
    public void ACountKeptInStepIsLeftAlone(string fileName, string code)
    {
        Assert.Empty(Scanned(fileName, code));
    }
}
